"""Freeze thirty-six Table4 mechanical cells;hold all six ambiguous break-elongation cells."""
from pathlib import Path
import hashlib,json
ROOT=Path(__file__).resolve().parents[4];HERE=Path(__file__).resolve().parent
EXT=ROOT.parent/'open-database-evidence/polymer-nr-notice-damping-20261111-r2'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def write(n,obj):
    with (HERE/n).open('x',encoding='utf-8',newline='\n') as f:json.dump(obj,f,ensure_ascii=False,indent=2);f.write('\n')
def main():
    assert sha(EXT/'publisher2025.pdf')=='2e729bb58b361568d27ab772ec1c031648cb6a858f58a6e4ece9ce45b74c3ea2'
    material=json.loads((ROOT/'materials_boundaries/data/materials.json').read_bytes());identities={x['id']:x for x in material['identities']};states={x['id']:x for x in material['records']}
    props=json.loads((ROOT/'materials_boundaries/data/reference_properties.json').read_bytes())['records']
    rows=[('1mmt','NR_1MMT','0.37','0.02','1.12','0.04','2.11','0.15','19.45','4.97','701','58','28.5','9.9','40.4','0.5'),('3mmt','NR_3MMT','0.42','0.04','1.22','0.10','2.48','0.29','19.55','3.05','686','32','29.2','6.8','40.7','1.0'),('5mmt','NR_5MMT','0.42','0.06','1.20','0.03','2.56','0.07','18.96','3.34','698','30','30.2','6.1','41.6','0.4'),('1ommt','NR_1O-MMT','0.44','0.02','1.19','0.07','2.62','0.33','26.08','2.94','754','41','44.7','12.1','42.0','0.2'),('3ommt','NR_3O-MMT','0.57','0.09','1.54','0.19','4.22','0.46','25.39','0.58','653','34','42.6','3.3','45.9','0.2'),('5ommt','NR_5O-MMT','0.77','0.20','1.91','0.33','5.36','0.94','20.05','3.55','630','72','35.6','10.9','48.0','0.5')]
    columns=[(0,'tensile_modulus','finite_strain_tensile_modulus','E100-200','MPa'),(2,'tensile_stress_at_specified_elongation','tensile_stress_at_200_percent_elongation','sigma200%','MPa'),(4,'tensile_stress_at_specified_elongation','tensile_stress_at_400_percent_elongation','sigma400%','MPa'),(6,'tensile_stress_at_break','tensile_stress_at_break','sigma_b','MPa'),(10,'volumetric_tensile_work_to_break','volumetric_tensile_work_to_break','Eb','J/cm³'),(12,'shore_a_hardness','shore_a_hardness','Shore A','Shore A')]
    text=(EXT/'pages2025/page-07.txt').read_text(encoding='utf-8');facts=[];held=[];overlaps=[]
    for suffix,label,*numbers in rows:
        identity='mat_bianchi2025_nr_'+suffix;assert identities[identity]['category']=='composite'
        assert label+' '+' '.join(numbers[j]+' ± '+numbers[j+1] for j in range(0,14,2)) in text
        for index,quantity,template,column,unit in columns:
            existing=[p['id'] for p in props if p['quantity']==quantity and states[p['material_state_id']]['identity_id']==identity]
            assert not existing;overlaps.append(dict(identity_id=identity,quantity=quantity,column=column,existing_record_ids=existing))
            facts.append(dict(candidate_key=suffix+'_'+template,source_id='bianchi_2025_nr_nanoclay',source_designation=label,existing_identity_id=identity,existing_state_id='state_bianchi2025_nr_'+suffix,quantity=quantity,number=numbers[index],standard_deviation=numbers[index+1],unit_text=unit,summary_statistic='reported_mean',uncertainty_type='standard_deviation',sample_count=5,sample_count_scope='Five specimens for this method/formulation;not an independent batch or cross-method pairing claim',context_proposed='shore_a_nominal_3mm' if quantity=='shore_a_hardness' else 'quasi_static_tensile',source_locator='PDF p7 Table4 '+label+' '+column,statistics_locator='PDF p19 section3.3.4 concluding mechanical mean/SD statement',sample_count_locator='PDF p18 section3.3.4 hardness paragraph' if quantity=='shore_a_hardness' else 'PDF p18 section3.3.4 quasi-static tensile paragraph',existing_unfilled_NR_contract_template_id='refprop_smr10_bianchi2025_nr_'+template,native_mapping='not_prepared'))
        held.append(dict(source_designation=label,column='epsilon_b',number=numbers[8],plus_minus=numbers[9],printed_unit='mm/mm',figure_axis_unit='%',decision='held_not_admitted',reason='Unresolved table-unit versus figure-axis conflict;no percent relabel,division by100 or author intent inferred'))
    assert len(facts)==36 and len({f['candidate_key'] for f in facts})==36 and len(held)==6
    protocol=dict(quasi_static_tensile=dict(standard='ASTM D412 as printed,edition/compliance unknown',instrument='Instron5969,1kN',crosshead_speed='500mm/min',extensometer='Instron2603,25mm gauge',per_formulation_specimens=5,test_temperature=None,actual_tensile_specimen_geometry=None,stress_strain_convention=None,finite_modulus_window='100-200% strain region;not initial Young modulus',specified_stresses=['200%','400%'],work_basis='Source Eb integral to break in J/cm³;normalization-volume convention,limits,quadrature and aggregation unknown'),shore_a=dict(standard='ASTM D2240 as printed,edition/compliance unknown',instrument='Hilderbrand Durometer as printed,model/calibration unknown',test_temperature='25 °C',square_width='15mm',nominal_thickness='3mm',dwell='10s',load_setting='488g as printed,not converted to force',per_formulation_specimens=5,preparation_stacking_or_cure_for_3mm_specimen=None,general_sheet_thickness='1mm source section3.2;not silently made equivalent to3mm hardness geometry'),shared_unknown=['relative_humidity','conditioning','independent_batches','cross_method_physical_pairing','orientation'],boundaries=['Five tensile specimens and five hardness specimens are separate method counts,not certified ten unique physical specimens','Mechanical mean/SD statement not transferred to thermal or fitted-time values','Hardness25C,stress-relaxation25C and caloric22C not assigned to quasi-static tensile temperature','No500mm/min to strain-rate conversion from25mm gauge','Shore A SD is scale points,not relative percent or pressure','No conversion of finite E100-200 to initial Young modulus,stress to modulus or work to pressure','All six epsilon_b values held without repair'])
    write('SOURCE_FACTS_R1.json',facts);write('HELD_BREAK_ELONGATION_R1.json',held);write('METHOD_BOUNDARIES_R1.json',protocol);write('EXISTING_OVERLAP_AUDIT_R1.json',overlaps)
    write('EVIDENCE_BINDINGS_R1.json',dict(external_files_sha256={str(p):sha(p) for p in [EXT/'publisher2025.pdf',EXT/'pages2025/page-07.txt',EXT/'pages2025/page-18.txt',EXT/'pages2025/page-19.txt',EXT/'visual2025/page-07.png',EXT/'visual2025/page-18.png',EXT/'visual2025/page-19.png',EXT/'visual2025/page-16.png',EXT/'visual2025/page-17.png']},native_files_sha256={f'materials_boundaries/data/{n}.json':sha(ROOT/f'materials_boundaries/data/{n}.json') for n in ('materials','reference_properties','sources')},latest_notice_completeness='unknown'))
    write('VALIDATION_R1.json',dict(scope='Producer source curation checks,not tests or independent approval',source_facts=36,held_elongation_cells=6,checks=['Official PDF hash exact','Six full Table4 rows match retained source text and visually inspected page','Six existing composite identities and candidate keys verified','No existing same-identity/quantity overlap','Mechanical mean/SD and separate five-specimen methods located','Finite-strain/target/endpoint/work/hardness roles kept distinct','Thermal statistics and conflicting elongation not transferred','Raw evidence external only;native unchanged'],native_applied=False,independent_review='not_run',mapping='not_prepared',installation='not_run',remote_CI='not_run'))
    print('36 mechanical source facts drafted;6ambiguous elongation cells held;native unchanged;not independently reviewed or mapped')
if __name__=='__main__':main()
